package io.ivo.mp3;
import io.ivo.container.*;import io.ivo.engine.*;import io.ivo.util.*;import java.io.*;import java.nio.file.*;import java.util.*;
/** Research MP38: spectral syntax plus conservative zlib coding, not a promoted production engine. */
public final class SpectralMeasure {
 static void field(ByteArrayOutputStream out,byte[] b){VarInt.writeUnsigned(out,b.length);out.writeBytes(b);}
 static byte[] field(byte[] b,VarInt.IntRef p){int n=Math.toIntExact(VarInt.readUnsigned(b,p));if(n<0||n>b.length-p.value)throw new IllegalArgumentException("Field bounds");byte[] v=Arrays.copyOfRange(b,p.value,p.value+n);p.value+=n;return v;}
 static byte[] zip(byte[] b)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();java.util.zip.Deflater d=new java.util.zip.Deflater(9);try(var z=new java.util.zip.DeflaterOutputStream(out,d)){z.write(b);}finally{d.end();}return out.toByteArray();}
 static byte[] unzip(byte[] b)throws IOException{try(var z=new java.util.zip.InflaterInputStream(new ByteArrayInputStream(b))){return z.readAllBytes();}}
 static byte[] encode(byte[] input,SpectralIr.Counts stats)throws IOException{var ir=ReservoirTrial.split(input);ByteArrayOutputStream layout=new ByteArrayOutputStream();VarInt.writeUnsigned(layout,ir.frames().size());for(var f:ir.frames()){VarInt.writeUnsigned(layout,f.crcBytes());VarInt.writeUnsigned(layout,f.sideInfoBytes());VarInt.writeUnsigned(layout,f.mainBytes());VarInt.writeUnsigned(layout,f.version());layout.write(f.mono()?1:0);}byte[] spectral=SpectralIr.encode(ir,stats);ByteArrayOutputStream out=new ByteArrayOutputStream();out.writeBytes(new byte[]{'M','P','3','8'});for(byte[] b:new byte[][]{layout.toByteArray(),ir.prefix(),ir.headers(),ir.crc(),ir.sideInfo()})field(out,zip(b));field(out,spectral);field(out,zip(ir.trailing()));return out.toByteArray();}
 static byte[] decode(byte[] payload,SpectralIr.Counts stats)throws IOException{if(payload.length<4||payload[0]!='M'||payload[1]!='P'||payload[2]!='3'||payload[3]!='8')throw new IOException("Bad MP38");VarInt.IntRef p=new VarInt.IntRef(4);byte[][] raw=new byte[7][];for(int i=0;i<7;i++){byte[] b=field(payload,p);raw[i]=i==5?b:unzip(b);}if(p.value!=payload.length)throw new IOException("Trailing MP38");VarInt.IntRef lp=new VarInt.IntRef(0);int n=Math.toIntExact(VarInt.readUnsigned(raw[0],lp)),total=0;ArrayList<ReservoirTrial.Frame> frames=new ArrayList<>();for(int i=0;i<n;i++){int crc=Math.toIntExact(VarInt.readUnsigned(raw[0],lp)),side=Math.toIntExact(VarInt.readUnsigned(raw[0],lp)),main=Math.toIntExact(VarInt.readUnsigned(raw[0],lp)),version=Math.toIntExact(VarInt.readUnsigned(raw[0],lp));if(lp.value>=raw[0].length)throw new IOException("Layout");int mono=raw[0][lp.value++]&255;if(mono>1||crc!=0&&crc!=2||main<0)throw new IOException("Frame shape");frames.add(new ReservoirTrial.Frame(crc,side,main,version,mono==1));total=Math.addExact(total,main);}if(lp.value!=raw[0].length||raw[2].length!=n*4L)throw new IOException("Layout count");var ir=new ReservoirTrial.Ir(raw[1],raw[2],raw[3],raw[4],new byte[total],raw[6],List.copyOf(frames),0);byte[] main=SpectralIr.decode(ir,raw[5],stats);return ReservoirTrial.join(new ReservoirTrial.Ir(raw[1],raw[2],raw[3],raw[4],main,raw[6],List.copyOf(frames),0));}
 public static void main(String[] args)throws Exception{if(args[0].equals("decode")){IvoArchive a=IvoContainer.unpack(Files.readAllBytes(Path.of(args[1])));SpectralIr.Counts stats=new SpectralIr.Counts();byte[] b=decode(a.payload(),stats);System.out.println("DECODE_SPECTRAL "+stats.stats());if(b.length!=a.originalSize()||!Arrays.equals(a.sha256(),Hashing.sha256(b)))throw new AssertionError("Archive hash");Files.write(Path.of(args[2]),b);return;}
  byte[] input=Files.readAllBytes(Path.of(args[0]));SpectralIr.Counts enc=new SpectralIr.Counts(),dec=new SpectralIr.Counts();long start=System.nanoTime();byte[] payload=encode(input,enc);byte[] packed=IvoContainer.pack(new IvoArchive(EngineId.MP3_SPECTRAL_RESEARCH,input.length,Path.of(args[0]).getFileName().toString(),Hashing.sha256(input),payload));Path out=Path.of(args[1]);Files.createDirectories(out.toAbsolutePath().getParent());Files.write(out,packed);IvoArchive a=IvoContainer.unpack(Files.readAllBytes(out));byte[] restored=decode(a.payload(),dec);if(!Arrays.equals(input,restored)||!Arrays.equals(a.sha256(),Hashing.sha256(restored))||!enc.stats().equals(dec.stats()))throw new AssertionError("Spectral byte mismatch");System.out.println("RESULT input="+args[0]+" original="+input.length+" ivo="+Files.size(out)+" exact=true sha="+HexFormat.of().formatHex(Hashing.sha256(restored))+" ms="+(System.nanoTime()-start)/1000000);System.out.println("SPECTRAL "+enc.stats());
 }
}
